"""Տեղադրվող հավելված (PWA). վարորդի հավելված (/app) և գարաժի հավելված (/panel).
Բջջային հեռախոսում «Տեղադրել»-ից հետո պատկերակը հայտնվում է գլխավոր էկրանին և բացվում է ամբողջ էկրանով։
Պատկերակները ներկառուցված են այստեղ (մեկ ֆայլ՝ առանց թղթապանակների), service worker-ը չի քեշավորում API-ն ու անձնական տվյալները։"""
import base64

from fastapi import FastAPI, HTTPException, Response
from fastapi.responses import JSONResponse

ICONS_B64 = {'icon-192.png': '', 'icon-512.png': '', 'icon-maskable-512.png': '', 'apple-touch-icon.png': ''}

ICONS = {name: base64.b64decode(data) for name, data in ICONS_B64.items()}
THEME, BACKGROUND = "#1d2529", "#e9ebec"


def _manifest(app_id: str, name: str, short_name: str, start_url: str, description: str) -> dict:
    return {
        "id": app_id, "name": name, "short_name": short_name, "description": description,
        "lang": "hy", "start_url": start_url, "scope": "/", "display": "standalone",
        "orientation": "portrait", "background_color": BACKGROUND, "theme_color": THEME,
        "icons": [
            {"src": "/icons/icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any"},
            {"src": "/icons/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any"},
            {"src": "/icons/icon-maskable-512.png", "sizes": "512x512", "type": "image/png", "purpose": "maskable"},
        ],
    }


DRIVER = _manifest("/app", "AI Auto Service", "Auto Service", "/app",
                   "Գտեք ավտոսերվիս, տեսեք գինն ու գնահատականը և թողեք հայտ")
GARAGE = _manifest("/panel", "AI Auto Service. Գարաժ", "Գարաժի պանել", "/panel",
                   "Գարաժի հայտերը, գները և ժամերը")

OFFLINE_HTML = """<!doctype html><html lang="hy"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Կապ չկա</title><body style="font:16px system-ui,sans-serif;display:grid;place-items:center;min-height:100vh;margin:0;background:#e9ebec;color:#1d2529;text-align:center">
<div style="padding:24px"><h2>Ինտերնետ կապ չկա</h2><p>Ստուգեք կապը և փորձեք նորից։</p>
<button onclick="location.reload()" style="font:inherit;padding:10px 20px;border-radius:10px;border:0;background:#1f5fbf;color:#fff">Փորձել նորից</button></div></body></html>"""

# Service worker. միայն էջերի (navigation) հարցումներն է մշակում. API-ն և անձնական տվյալները երբեք չեն քեշավորվում։
SERVICE_WORKER = """
const CACHE = "autoservice-shell-v1";
const SHELL = ["/app", "/panel"];                      // միայն այս երկու էջի «կեղևը» (ոչ տվյալները)
const OFFLINE = %s;
self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", (e) => e.waitUntil((async () => {
  for (const k of await caches.keys()) if (k !== CACHE) await caches.delete(k);
  await self.clients.claim();
})()));
self.addEventListener("fetch", (e) => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== "GET" || url.origin !== location.origin || req.mode !== "navigate") return;   // մնացածը՝ ուղիղ ցանց
  e.respondWith((async () => {
    try {
      const res = await fetch(req);
      if (res.ok && SHELL.includes(url.pathname)) (await caches.open(CACHE)).put(url.pathname, res.clone());
      return res;
    } catch (err) {
      const hit = SHELL.includes(url.pathname) ? await (await caches.open(CACHE)).match(url.pathname) : null;
      return hit || new Response(OFFLINE, { status: 503, headers: { "Content-Type": "text/html; charset=utf-8" } });
    }
  })());
});
""" % __import__("json").dumps(OFFLINE_HTML)


def register(app: FastAPI) -> None:
    @app.get("/manifest-app.webmanifest", include_in_schema=False)
    def manifest_driver():
        return JSONResponse(DRIVER, media_type="application/manifest+json")

    @app.get("/manifest-panel.webmanifest", include_in_schema=False)
    def manifest_garage():
        return JSONResponse(GARAGE, media_type="application/manifest+json")

    @app.get("/sw.js", include_in_schema=False)
    def service_worker():
        # no-cache՝ որպեսզի թարմացումները արագ հասնեն. Scope՝ ամբողջ կայք
        return Response(SERVICE_WORKER, media_type="application/javascript",
                        headers={"Cache-Control": "no-cache", "Service-Worker-Allowed": "/"})

    @app.get("/icons/{name}", include_in_schema=False)
    def icon(name: str):
        data = ICONS.get(name)
        if data is None:
            raise HTTPException(404, "Not found")
        return Response(data, media_type="image/png", headers={"Cache-Control": "public, max-age=86400"})
